import "server-only";
import fs from "node:fs";
import path from "node:path";
import type { Card, Dept, Gender, Product } from "./types";
import { SUBS } from "./taxonomy";
import { groupKey, interleave } from "./interleave";

// Read once per server instance. Generated by scripts/build-data.mjs from the nike.com.ar scrape.
export const PRODUCTS: Product[] = JSON.parse(
  fs.readFileSync(path.join(process.cwd(), "src", "data", "products.json"), "utf8"),
);

const BY_SLUG = new Map(PRODUCTS.map((p) => [p.s, p]));

export function toCard(p: Product): Card {
  return {
    id: p.id, s: p.s, n: p.n, t: p.t, g: p.g, d: p.d, c: p.c, ty: p.ty, sp: p.sp, p: p.p, lp: p.lp,
    im: p.im.slice(0, 3), cn: p.cn, hx: p.hx, hx2: p.hx2, fm: p.fm, sz: p.sz, sa: p.sa, f: p.f, gs: p.gs,
  };
}

export const getProduct = (slug: string) => BY_SLUG.get(slug);

export type ListingFilter = { gender?: Gender; dept?: Dept; sub?: string; sport?: string };

export function listing({ gender, dept, sub, sport }: ListingFilter) {
  return PRODUCTS.filter(
    (p) =>
      (!gender || p.g === gender || p.g === "unisex") &&
      (!dept || p.d === dept) &&
      (!sub || p.c === sub) &&
      (!sport || p.sp.includes(sport)),
  );
}

/** Subcategories that actually have products for this gender, with a count and a cover image. */
export function subsFor(gender: Gender, dept: Dept) {
  return SUBS[dept]
    .filter((s) => !s.only || s.only === gender)
    .map((s) => {
      const items = listing({ gender, dept, sub: s.slug });
      // prefer a cover from the gender itself over a unisex one
      const cover = items.find((p) => p.g === gender) ?? items[0];
      return { ...s, count: items.length, cover: cover?.im[0] ?? "" };
    })
    .filter((s) => s.count > 0);
}

type RailKind = "new" | "sale" | "best";
const FLAG: Record<RailKind, string> = { new: "n", sale: "s", best: "b" };

/** Products for a horizontal rail, spread across subcategories so a rail never shows ten near-identical items. */
export function rail(kind: RailKind | null, filter: ListingFilter = {}, size = 14) {
  const pool = listing(filter).filter((p) => !kind || p.f.includes(FLAG[kind]));
  return spread(pool, size).map(toCard);
}

export function spread(pool: Product[], size: number) {
  return interleave(pool, groupKey, size);
}

export function related(p: Product, size = 12) {
  return PRODUCTS.filter((x) => x.c === p.c && x.d === p.d && x.s !== p.s && (x.g === p.g || x.g === "unisex" || p.g === "unisex"))
    .slice(0, size)
    .map(toCard);
}

export function countFor(filter: ListingFilter) {
  return listing(filter).length;
}
